function norm(v) {
  return String(v == null ? '' : v).replace(/\s+/g, ' ').trim().toLowerCase();
}

const body = $json.body || {};
const records = Array.isArray(body.records) ? body.records : [];

if (body.source !== 'reconcile') {
  throw new Error(`Expected source="reconcile" but received "${body.source || ''}"`);
}

// Compatibilidad hacia atrás: si el Apps Script de College todavía no manda
// schoolType, se asume 'college'. Una vez actualizado ese script, quitar el default.
const schoolType = norm(body.schoolType || 'college');

if (records.length === 0) {
  return [];
}

// Property de HubSpot compartida para el checkbox de biweekly/monthly,
// tanto para College como para HS. Confirmado: biweekly_participation.
const SHARED_BIWEEKLY_PROPERTY = 'biweekly_participation';

const FIELD_MAPS = {
  college: {
    'status': 'lifecyclestage',
    'timezone': 'timezone',
    'planning & gsw': 'b2b_planning__gsw_status',
    '1st gbm': 'gbm_date',
    'activities fair': 'b2b_activities_fair_status',
    'gbm': 'b2b_gbm_status',
    'biweekly sent 1st semester': 'b2b_biweekly_sent_1st_semester_status',
    'biweekly sent 2nd semester': 'b2b_biweekly_sent_2nd_semester_status',
    '__biweekly__': SHARED_BIWEEKLY_PROPERTY,
    'hootsuite point person': 'hootsuite_point_person',
    'hootsuite status': 'hotsuite_status',
    'slt tracker link': 'slt_tracker_link',
    'givelively link': 'givelively_campaign_url',
    'webinar date (at gbm)': 'b2b_mm_webinar_date',
    'webinar completed?': 'b2b_webinar_date_completed',
    'power hour other date': 'power_hour_date',
    'power hour completed?': 'b2b_power_hour_completed'
  },
  'high school': {
    'status': 'lifecyclestage',
    'timezone': 'timezone',
    'planning & gsw': 'b2b_planning__gsw_status',
    'gbm': 'b2b_gbm_status',
    '__biweekly__': SHARED_BIWEEKLY_PROPERTY,
    'type of post biweekly communication': 'b2b_hs_type_of_post_biweekly_comm',
    'givelively link': 'givelively_campaign_url',
    'mm webinar date (taking place at gbm)': 'b2b_mm_webinar_date',
    'webinar completed?': 'b2b_webinar_date_completed',
    //'fundraising method': null   // TODO: falta internal name
  }
};

const SHARED_STATUS_VALUE_MAP = {
  'get started': '23878512',
  'sustainability': '23925576',
  'growth': '23925577',
  'reboot': '23926968',
  'defunct': '23926969',
  'unknown': '63214633',
};

const VALUE_MAPS = {
  college: {
    'status': SHARED_STATUS_VALUE_MAP,
    'gbm': {
      '1st gbm preparation': '1st_GBM_Preparation',
      '1st gbm completed': '1st_GBM_Completed'
    },
  },
  'high school': {
    'status': SHARED_STATUS_VALUE_MAP,
    'gbm': {
      // TODO: confirmar valores válidos para HS (¿los mismos que College?)
      '1st gbm preparation': '1st_GBM_Preparation',
      '1st gbm completed': '1st_GBM_Completed'
    },
  'type of post biweekly communication': {
    'automatically communications': 'Automatically communications',
    'automatically communication': 'Automatically communications',
    'manually communications': 'Manually communications',
    'manually communication': 'Manually communications',
    },
  }
};

const FIELD_MAP = FIELD_MAPS[schoolType];
const VALUE_MAP = VALUE_MAPS[schoolType];

if (!FIELD_MAP) {
  throw new Error(`schoolType desconocido: "${body.schoolType}"`);
}

const desiredRecords = [];
const propertySet = new Set();
const unmappedFields = new Set();
const invalidValues = [];

for (const record of records) {
  const recordId = String(record.recordId == null ? '' : record.recordId).trim();
  if (!recordId) continue;

  const fields = record.fields && typeof record.fields === 'object' ? record.fields : {};
  const desiredProperties = {};

  for (const [rawField, rawValue] of Object.entries(fields)) {
    const field = norm(rawField);

    if (!(field in FIELD_MAP)) {
      unmappedFields.add(field);
      continue;
    }

    const internalName = FIELD_MAP[field];
    if (!internalName) {
      unmappedFields.add(field);
      continue;
    }

    let value = rawValue == null ? '' : String(rawValue).trim();
    if (value === '') continue;

    if (VALUE_MAP[field]) {
      const translated = VALUE_MAP[field][norm(value)];
      if (translated === undefined) {
        invalidValues.push({
          recordId,
          chapterName: record.chapterName || '',
          schoolType,
          field,
          value,
        });
        continue;
      }
      value = translated;
    }

    desiredProperties[internalName] = value;
    propertySet.add(internalName);
  }

  if (Object.keys(desiredProperties).length === 0) continue;

  desiredRecords.push({
    recordId,
    chapterName: record.chapterName || '',
    owner: record.owner || '',
    schoolType,
    desiredProperties,
  });
}

if (invalidValues.length) {
  throw new Error('Values without a HubSpot mapping: ' + JSON.stringify(invalidValues));
}

if (desiredRecords.length === 0) {
  return [];
}

return [{
  json: {
    source: body.source,
    schoolType,
    generatedAt: body.generatedAt || null,
    desiredRecords,
    diagnostics: {
      schoolType,
      receivedRecords: records.length,
      preparedRecords: desiredRecords.length,
      unmappedFields: Array.from(unmappedFields).sort(),
    },
    batchReadBody: {
      properties: Array.from(propertySet).sort(),
      inputs: desiredRecords.map(r => ({ id: r.recordId })),
    },
  },
}];

const plan = $('Prepare Reconciliation').first().json;
const hubspotResults = Array.isArray($json.results) ? $json.results : [];

const currentById = new Map(
  hubspotResults.map(r => [String(r.id), r.properties || {}])
);

function canonical(property, value) {
  const text = String(value == null ? '' : value).trim();

  // HubSpot multi-checkbox values are semicolon-separated. Ignore ordering for comparison.
  if (property === 'biweekly_participation') {
    return text
      .split(';')
      .map(v => v.trim())
      .filter(Boolean)
      .sort()
      .join(';');
  }

  return text;
}

const updates = [];
const changes = [];
const missingRecordIds = [];

for (const desired of plan.desiredRecords) {
  const current = currentById.get(String(desired.recordId));

  if (!current) {
    missingRecordIds.push(desired.recordId);
    continue;
  }

  const changedProperties = {};
  const propertyChanges = [];

  for (const [property, desiredValue] of Object.entries(desired.desiredProperties)) {
    const currentValue = current[property] == null ? '' : current[property];

    if (canonical(property, currentValue) === canonical(property, desiredValue)) {
      continue;
    }

    changedProperties[property] = desiredValue;
    propertyChanges.push({
      property,
      from: currentValue,
      to: desiredValue,
    });
  }

  if (Object.keys(changedProperties).length === 0) continue;

  updates.push({
    id: desired.recordId,
    properties: changedProperties,
  });

  changes.push({
    recordId: desired.recordId,
    chapterName: desired.chapterName,
    owner: desired.owner,
    changes: propertyChanges,
  });
}

if (missingRecordIds.length) {
  console.log('Company IDs not returned by HubSpot batch read: ' + missingRecordIds.join(', '));
}

if (updates.length === 0) {
  console.log('Reconciliation complete: no HubSpot changes required. Diagnostics: ' + JSON.stringify(plan.diagnostics));
  return [];
}

return [{
  json: {
    diagnostics: {
      ...plan.diagnostics,
      hubspotRecordsRead: hubspotResults.length,
      recordsToUpdate: updates.length,
      missingRecordIds,
    },
    changes,
    batchUpdateBody: {
      inputs: updates,
    },
  },
}];

